'use strict';
const D=CRM,KEY='luz-crm-prototype-v1',SESSION='luz-crm-session-v1';
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>Number(n||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const date=x=>x?new Date(x.length===10?x+'T12:00:00':x).toLocaleDateString('pt-BR'):'—';
const time=x=>new Date(x).toLocaleString('pt-BR',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'});
const monthLabel=m=>new Date(m+'-01T12:00:00').toLocaleDateString('pt-BR',{month:'short',year:'numeric'});
const initials=n=>n.split(' ').filter(Boolean).slice(0,2).map(s=>s[0]).join('').toUpperCase();
const paths={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M16 3.13a4 4 0 0 1 0 7.75',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z',funnel:'M3 4h18l-7 8v7l-4 2v-9Z',list:'M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01',wallet:'M3 5h16v4H4a2 2 0 0 1 0-4Zm0 2v12a2 2 0 0 0 2 2h16V9h-5v6h5 M17 12h.01',chart:'M3 3v18h18M7 16v-4M12 16V7M17 16v-7',shield:'M12 3 3 7v6c0 5 9 9 9 9s9-4 9-9V7Zm-5 9 3 3 7-7',plus:'M12 5v14M5 12h14',search:'M21 21l-6-6M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',arrow:'M5 12h14m-5-5 5 5-5 5',close:'m6 6 12 12M6 18 18 6',logout:'M9 21H4V3h5M9 12h12m-4-4 4 4-4 4',mail:'M3 5h18v14H3Zm0 0 9 7 9-7',check:'m5 12 4 4L19 6',clock:'M12 8v4l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',upload:'M12 16V4m-5 5 5-5 5 5M4 16v5h16v-5',leaf:'M20 3C9 2 2 8 5 15s14 7 15-12ZM4 21 15 10',menu:'M3 6h18M3 12h18M3 18h18',edit:'m16 3 5 5-12 12-6 1 1-6ZM14 5l5 5',file:'M14 2H4v20h16V8Zm0 0v6h6M8 13h8M8 17h6',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.file}"/></svg>`;
const brand=()=>`<div class="brand"><img class="brand-logo" src="favicon.png" alt="Logo da Luz da Esperança" width="48" height="48"><div class="brand-name">Luz da Esperança<small>Relacionar para transformar</small></div></div>`;
const art=()=>'<div class="welcome-art" aria-hidden="true"><div class="sun"></div><div class="hill two"></div><div class="hill"></div><div class="plant"></div></div>';
const button=(label,action,id='',style='secondary',ic='')=>`<button type="button" class="btn ${style}" data-action="${action}" data-id="${esc(id)}">${ic?icon(ic):''}${label}</button>`;
const badge=(label,tone='')=>`<span class="badge ${tone}">${esc(label)}</span>`;
const statusBadge=c=>c.plan?badge(c.plan.status,c.plan.status==='Inadimplente'?'red':c.plan.status==='Ativo'?'':'gray'):badge('Prospect','gold');
const avatar=c=>`<span class="avatar">${esc(initials(c.name))}</span>`;
const contactCell=c=>`<div class="contact-cell">${avatar(c)}<div><button class="contact-name" data-action="profile" data-id="${c.id}">${esc(c.name)}</button><small>${esc(c.email||c.phone)}</small></div></div>`;
const empty=msg=>`<div class="empty">${icon('leaf')}${esc(msg)}</div>`;
const select=(name,options,value='',placeholder='Todos')=>`<select name="${name}" aria-label="${esc(name)}">${placeholder?`<option value="">${placeholder}</option>`:''}${options.map(o=>{const[v,t]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`}).join('')}</select>`;
const $f=s=>$(s,$('#modal'));
const field=(label,name,value='',type='text',extra='')=>`<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`;
const selectField=(label,name,options,value='',placeholder='')=>`<div class="field"><label for="f-${name}">${label}</label>${select(name,options,value,placeholder).replace('<select ','<select id="f-'+name+'" ')}</div>`;
let selectedContacts=new Set(),funnelView='board',funnelMobileStage=0;
let state,user,page='dashboard',filters={q:'',origin:'',owner:'',period:'',funnel:'',status:'',mode:'',stage:''},tab='all',financeTab='payments',contactPage=1,lastActivity=Date.now(),loginAttempts=0,lockUntil=0;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{toast('Não foi possível salvar neste navegador. As alterações atuais ficam em memória.','error')}}
function toast(msg,tone=''){const node=document.createElement('div');node.className='toast '+(tone?'error-toast':'');node.textContent=msg;$('#toasts').replaceChildren(node);setTimeout(()=>node.remove(),4800)}
async function hashPassword(password,salt){if(!crypto.subtle)throw Error('Abra em http://localhost:3000 para usar a autenticação.');const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']),bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt:new TextEncoder().encode(salt),iterations:100000,hash:'SHA-256'},key,256);return [...new Uint8Array(bits)].map(x=>x.toString(16).padStart(2,'0')).join('')}
async function credentials(password){const salt=D.uid();return{salt,passwordHash:await hashPassword(password,salt)}}
function admin(){if(user?.role!=='Administrador')throw Error('Esta ação exige perfil de Administrador.')}
function activeUser(){if(!user||!state.users.some(u=>u.id===user.id&&u.active))throw Error('Sua sessão foi encerrada. Entre novamente.');if(Date.now()-lastActivity>30*60*1000){logout();throw Error('Sessão encerrada por inatividade.')}lastActivity=Date.now();sessionStorage.setItem(SESSION,JSON.stringify({id:user.id,last:lastActivity}))}
function logout(message){selectedContacts.clear();sessionStorage.removeItem(SESSION);user=null;closeModal();render();if(message)toast(message)}
function navigate(next){if(['dashboard','reports','users','audit'].includes(next))admin();if(page!==next)selectedContacts.clear();page=next;filters={q:'',origin:'',owner:'',period:'',funnel:'',status:'',mode:'',stage:''};tab=next==='donors'?'donors':'all';financeTab='payments';contactPage=1;render();window.scrollTo(0,0)}
function heading(title,description,actions=''){return `<div class="page-heading"><div><div class="eyebrow">Luz da Esperança · Captação e relacionamento</div><h1>${title}</h1><p>${description}</p></div><div class="flex">${actions}</div></div>`}
const pageNames={dashboard:'Visão geral',funnel:'Funil de captação',contacts:'Contatos',donors:'Doadores',lists:'Listas e campanhas',finance:'Doações e pendências',reports:'Relatórios',users:'Usuários e acessos',audit:'Histórico de auditoria'};
function render(){if(!user){renderLogin();return}if(user.role!=='Administrador'&&['dashboard','reports','users','audit'].includes(page))page='funnel';const nav=(p,ic,count)=>`<button class="nav-item ${page===p?'active':''}" data-action="nav" data-id="${p}" ${page===p?'aria-current="page"':''}>${icon(ic)}${pageNames[p]}${count?`<span class="nav-count">${count}</span>`:''}</button>`;$('#app').innerHTML=`<aside class="sidebar">${brand()}<div class="nav-label">Nosso dia a dia</div>${user.role==='Administrador'?nav('dashboard','home'):''}${nav('funnel','funnel')}${nav('contacts','users')}${nav('donors','heart')}${nav('lists','mail')}<div class="nav-label">Contribuições</div>${nav('finance','wallet',D.pending(state).filter(p=>p.overdue).length)}${user.role==='Administrador'?nav('reports','chart')+'<div class="nav-label">Administração</div>'+nav('users','shield')+nav('audit','clock'):''}<div class="sidebar-note">${icon('leaf')}<p>Cada relacionamento cultivado faz a esperança florescer.</p></div><div class="sidebar-foot">Parnaíba, PI · Centro Espírita e Obras Sociais</div></aside><div class="workspace"><header class="topbar"><button class="icon-button mobile-menu" data-action="menu" aria-label="Abrir ou fechar menu">${icon('menu')}</button><span class="breadcrumb">Nosso espaço &nbsp; / &nbsp; <b>${pageNames[page]}</b></span><div class="topbar-right"><span class="environment">Ambiente de demonstração</span><button class="icon-button" data-action="tasks" aria-label="Ver ações de relacionamento">${icon('bell')}</button><div class="flex">${avatar(user)}<div class="user-text">${esc(user.name)}<small>${esc(user.role)}</small></div></div><button class="icon-button" data-action="logout" aria-label="Sair do sistema" title="Sair do sistema">${icon('logout')}</button></div></header><main id="main">${content()}${pageFooter()}</main></div>`;bindPage()}
function pageFooter(){return `<footer class="page-footer"><span>Feito para cuidar de quem caminha com a nossa causa.</span><span>Luz da Esperança · ${new Date().getFullYear()}</span></footer>`}
function content(){switch(page){case'dashboard':return dashboard();case'funnel':return funnel();case'contacts':case'donors':return contacts();case'lists':return lists();case'finance':return finance();case'reports':return reports();case'users':return users();case'audit':return auditPage()}}
function metric(title,value,sub,ic='heart',gold=false){return `<div class="metric"><div class="metric-head">${title}<span class="metric-icon ${gold?'gold':''}">${icon(ic)}</span></div><strong>${value}</strong><small>${sub}</small></div>`}
function paymentsFor(period=D.month()){return state.payments.filter(p=>p.date.startsWith(period))}
function total(ps){return ps.reduce((s,p)=>s+p.amount,0)}
function chart(end=D.month()){const d=new Date(end+'-01T12:00:00'),data=[];for(let offset=-5;offset<=0;offset++){const m=D.month(new Date(d.getFullYear(),d.getMonth()+offset,1,12)),ps=paymentsFor(m);data.push({m,rec:total(ps.filter(p=>p.mode==='Recorrente')),one:total(ps.filter(p=>p.mode==='Pontual'))})}const max=Math.max(500,...data.flatMap(v=>[v.rec,v.one]));return `<div class="chart"><div class="axis"><span>${money(max)}</span><span>${money(max/2)}</span><span>R$ 0</span></div><div class="bars">${data.map(v=>`<div class="bar-group"><div class="bar" style="height:${v.rec/max*82}%" title="${monthLabel(v.m)} · Recorrentes: ${money(v.rec)}" role="img" aria-label="${monthLabel(v.m)}: recorrentes ${money(v.rec)}"></div><div class="bar gold" style="height:${v.one/max*82}%" title="Pontuais: ${money(v.one)}" role="img" aria-label="Pontuais ${money(v.one)}"></div><span class="bar-label">${new Date(v.m+'-01T12:00:00').toLocaleDateString('pt-BR',{month:'short'}).replace('.','')}</span></div>`).join('')}</div></div>`}
function funnelSummary(){return D.STAGES.map((name,i)=>{const count=state.contacts.filter(c=>c.stage===i&&!c.plan).length;return `<div class="funnel-row"><span class="step">${i+1}</span><div class="info">${name}<div class="progress ${i===1?'gold':''}"><i style="width:${Math.max(8,count/Math.max(1,state.contacts.filter(c=>!c.plan).length)*100)}%"></i></div></div><strong>${count}</strong></div>`}).join('')}
function dashboard(){const ps=paymentsFor(),donors=state.contacts.filter(c=>c.plan),pending=D.pending(state).filter(p=>p.overdue),active=donors.filter(c=>c.plan.status==='Ativo'),rec=active.filter(c=>c.plan.mode==='Recorrente').reduce((s,c)=>s+c.plan.amount,0);return heading('Bom dia, '+esc(user.name.split(' ')[0])+'.','Um olhar sobre os relacionamentos que tornam nossa missão possível.',button('Registrar doação','payment','','','plus'))+`<section class="welcome"><div><div class="eyebrow">Pequenos gestos. Novas possibilidades.</div><h2>Juntos, a esperança ganha força.</h2><p>Acompanhe cada contribuição e cultive os laços de quem ajuda a transformar a vida da nossa comunidade.</p></div>${art()}</section><div class="flex between" style="margin-bottom:15px"><h3>Nosso impacto em números</h3><small>${new Date().toLocaleDateString('pt-BR',{month:'long',year:'numeric'})}</small></div><section class="metrics">${metric('Arrecadado neste mês',money(total(ps)),ps.length+' contribuições recebidas','wallet')}${metric('Doadores ativos',active.length,donors.length+' doadores cadastrados','heart')}${metric('Receita mensal prevista',money(rec),'Compromissos recorrentes ativos','leaf')}${metric('Pendências em atraso',money(total(pending)),pending.length+' competências aguardando baixa','clock',true)}</section><div class="dashboard-grid"><section class="panel"><div class="panel-header"><div><h2>Uma história de generosidade</h2><p>Contribuições recebidas nos últimos seis meses</p></div><div class="legend"><span><i></i>Recorrentes</span><span><i class="gold"></i>Pontuais</span></div></div><div class="panel-body">${chart()}<div class="chart-footer"><span>Cada contribuição tem um destino.</span><strong>${money(total(ps))} neste mês</strong></div></div></section><section class="panel"><div class="panel-header"><div><h2>Caminhos até a doação</h2><p>Potenciais doadores em cada etapa</p></div></div><div class="panel-body">${funnelSummary()}${button('Ver funil completo','nav','funnel','quiet','arrow')}</div></section><section class="panel"><div class="panel-header"><div><h2>Contribuições mais recentes</h2><p>Gestos que fazem a diferença</p></div>${button('Ver todas','nav','finance','quiet','arrow')}</div>${paymentTable([...state.payments].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,4),true)}</section><section class="panel"><div class="panel-header"><div><h2>Hora de cultivar os laços</h2><p>Relacionamentos que precisam de atenção</p></div>${icon('leaf')}</div><div class="panel-body">${state.tasks.filter(t=>!t.done).slice(0,3).map(t=>`<div class="list-row"><span class="avatar">${icon('heart')}</span><div><p>${esc(t.text)}</p><small>Reengajamento · doador recorrente</small></div><button class="icon-button right" data-action="profile" data-id="${t.contactId}" aria-label="Abrir contato">${icon('arrow')}</button></div>`).join('')||empty('Todos os relacionamentos estão em dia.')}<div class="list-row"><span class="avatar">${icon('users')}</span><div><p>${state.contacts.filter(c=>!c.plan&&c.stage===3).length} contatos prontos para doar</p><small>Na etapa de decisão de doação</small></div><button class="icon-button right" data-action="nav" data-id="funnel" aria-label="Ver funil">${icon('arrow')}</button></div></div></section></div>`}
function filterContacts(){const q=filters.q.toLocaleLowerCase('pt-BR');return state.contacts.filter(c=>(!q||[c.name,c.email,c.phone,c.document].some(v=>v.toLocaleLowerCase('pt-BR').includes(q)))&&(!filters.origin||c.origin===filters.origin)&&(!filters.owner||c.owner===filters.owner)&&(!filters.period||D.month(c.created)===filters.period)&&(!filters.funnel||c.funnel===filters.funnel)&&(!filters.status||(c.plan?.status||'Prospect')===filters.status)&&(!filters.stage||String(c.stage)===filters.stage))}
function filtersHTML(extra='',period=false){return `<div class="filters"><div class="search">${icon('search')}<input type="search" id="search" aria-label="Buscar por nome, e-mail, telefone ou documento" placeholder="Buscar um relacionamento…" value="${esc(filters.q)}"></div>${select('origin',D.ORIGINS,filters.origin,'Todas as origens')}${select('owner',state.users.map(u=>[u.id,u.name]),filters.owner,'Todos os operadores')}${period?`<input type="month" name="period" value="${esc(filters.period)}" aria-label="Mês de cadastro">`:''}${extra}${Object.values(filters).some(Boolean)?button('Limpar filtros','clear','','quiet'):''}</div>`}
function funnel(){
  const cs=filterContacts().filter(c=>!c.plan);
  const stageNames=['Descoberta','Reconhecimento','Consideração','Decisão de doação'];
  const controls=`<div class="funnel-toolbar"><small>${cs.length} potenciais doadores</small><div class="tabs view-tabs" aria-label="Visualização do funil">${[['board','Quadro compacto','funnel'],['list','Lista','list']].map(([v,label,ic])=>`<button class="tab ${funnelView===v?'active':''}" data-action="funnel-view" data-id="${v}" aria-pressed="${funnelView===v}">${icon(ic)} ${label}</button>`).join('')}</div></div>`;
  const board=`<div class="mobile-stages" aria-label="Etapa do funil">${stageNames.map((name,i)=>`<button class="stage-tab ${funnelMobileStage===i?'active':''}" data-action="funnel-stage" data-id="${i}" aria-pressed="${funnelMobileStage===i}">${esc(name)} <span>${cs.filter(c=>c.stage===i).length}</span></button>`).join('')}</div><div class="kanban compact-kanban">${D.STAGES.map((name,i)=>`<section class="column ${funnelMobileStage===i?'is-selected':''}" data-stage="${i}" aria-label="${esc(name)}"><div class="column-heading"><span class="stage-number">${i+1}</span><h3 title="${esc(name)}">${stageNames[i]}</h3><span class="stage-count">${cs.filter(c=>c.stage===i).length}</span></div><div class="column-cards" tabindex="0" role="region" aria-label="Contatos em ${esc(name)}">${cs.filter(c=>c.stage===i).map(c=>`<article class="card compact-card" draggable="true" data-contact="${c.id}"><div class="compact-contact">${avatar(c)}<div class="compact-card-info"><button class="contact-name" data-action="profile" data-id="${c.id}" title="${esc(c.name)}">${esc(c.name)}</button><small>${esc(c.origin)} · ${c.funnel}</small></div><button class="icon-button card-move" data-action="move" data-id="${c.id}" aria-label="Mover etapa de ${esc(c.name)}" title="Mover etapa">${icon('arrow')}</button></div></article>`).join('')||'<div class="empty compact-empty">Nenhum contato nesta etapa.</div>'}</div></section>`).join('')}</div><p class="board-help">${icon('funnel')} Arraste para mover entre etapas ou use a seta de cada contato.</p>`;
  const list=`<section class="panel funnel-list">${cs.length?`<div class="table-wrap"><table><thead><tr><th>Relacionamento</th><th>Etapa atual</th><th>Origem</th><th>Responsável</th><th></th></tr></thead><tbody>${cs.map(c=>`<tr><td>${contactCell(c)}</td><td><span class="stage-inline">${c.stage+1}</span>${esc(stageNames[c.stage])}</td><td>${esc(c.origin)} · ${c.funnel}</td><td>${esc(state.users.find(u=>u.id===c.owner)?.name||'—')}</td><td>${button('Mover etapa','move',c.id,'secondary small','arrow')}</td></tr>`).join('')}</tbody></table></div>`:empty('Nenhum contato encontrado para estes filtros.')}</section>`;
  return heading('Funil de captação','Cultive os relacionamentos, um passo de cada vez.',button('Novo contato','contact','','','plus'))+filtersHTML(select('funnel',['Inbound','Outbound'],filters.funnel,'Todos os funis'),true)+controls+(funnelView==='board'?board:list);
}
function visibleContacts(){return filterContacts().filter(c=>page==='donors'?c.plan:tab==='leads'?!c.plan:tab==='donors'?c.plan:true)}
function emailEligible(c){return Boolean(c?.email&&D.emailValid(c.email)&&!c.optOut)}
function cleanContactSelection(){selectedContacts=new Set([...selectedContacts].filter(id=>emailEligible(state.contacts.find(c=>c.id===id))))}
function selectionToolbar(cs){
  cleanContactSelection();
  const eligible=cs.filter(emailEligible),allSelected=eligible.length>0&&eligible.every(c=>selectedContacts.has(c.id));
  return `<div class="contact-selection-bar"><label class="select-filtered"><input type="checkbox" data-action="select-filtered" ${allSelected?'checked':''} ${eligible.length?'':'disabled'} aria-label="Selecionar todos os contatos elegíveis deste filtro"> Selecionar todos do filtro <small>(${eligible.length})</small></label><span class="selection-count" aria-live="polite">${selectedContacts.size} ${selectedContacts.size===1?'selecionado':'selecionados'}</span><div class="selection-actions">${selectedContacts.size?button('Limpar seleção','clear-selection','','quiet small'):''}${button('Redigir e-mail','bulk-email','','small','mail')}</div></div>`;
}
function contacts(){
  const isDonors=page==='donors',cs=visibleContacts(),pages=Math.max(1,Math.ceil(cs.length/10));contactPage=Math.min(contactPage,pages);
  return heading(isDonors?'Quem caminha com a nossa causa':'Cada contato, uma nova possibilidade',isDonors?'Acompanhe contribuições e cuide de quem sustenta nossas obras sociais.':'Pessoas e organizações que fazem parte da nossa rede de esperança.',button('Exportar','export-contacts','','secondary','download')+button('Novo contato','contact','','','plus'))+(!isDonors?`<div class="tabs">${[['all','Todos os contatos'],['leads','Potenciais doadores'],['donors','Doadores']].map(([v,l])=>`<button class="tab ${tab===v?'active':''}" data-action="contact-tab" data-id="${v}">${l}</button>`).join('')}</div>`:'')+filtersHTML(select('status',isDonors?['Ativo','Inadimplente','Pausado','Cancelado']:['Prospect','Ativo','Inadimplente','Pausado','Cancelado'],filters.status,'Todos os status'))+`<section class="panel contacts-panel">${selectionToolbar(cs)}${cs.length?`<div class="table-wrap"><table><thead><tr><th class="checkbox-cell"><span class="sr-only">Selecionar destinatário</span></th><th>Relacionamento</th><th>Origem</th><th>${isDonors?'Contribuição':'Etapa do funil'}</th><th>Status</th><th>Responsável</th><th></th></tr></thead><tbody>${cs.slice((contactPage-1)*10,contactPage*10).map(c=>`<tr class="${selectedContacts.has(c.id)?'selected-row':''}"><td class="checkbox-cell"><input type="checkbox" data-action="select-contact" data-id="${c.id}" aria-label="Selecionar ${esc(c.name)} para enviar e-mail" ${selectedContacts.has(c.id)?'checked':''} ${emailEligible(c)?'':`disabled title="${c.optOut?'Contato descadastrado de e-mails':'Sem e-mail válido'}"`}></td><td>${contactCell(c)}</td><td>${esc(c.origin)}<small style="display:block">${c.funnel}</small></td><td>${c.plan?money(c.plan.amount)+'<small style="display:block">'+c.plan.mode+'</small>':esc(D.STAGES[c.stage])}</td><td>${statusBadge(c)} ${c.optOut?badge('Descadastrado','gray'):''}</td><td>${esc(state.users.find(u=>u.id===c.owner)?.name||'—')}</td><td><button class="icon-button" data-action="profile" data-id="${c.id}" aria-label="Abrir ficha de ${esc(c.name)}">${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div><div class="flex between" style="padding:16px 22px;border-top:1px solid var(--line)"><small>${cs.length} relacionamentos · Página ${contactPage} de ${pages}</small><div class="flex"><button class="btn secondary small" data-action="prev" ${contactPage<=1?'disabled':''}>Anterior</button><button class="btn secondary small" data-action="next" ${contactPage>=pages?'disabled':''}>Próxima</button></div></div>`:empty('Nenhum relacionamento encontrado para estes filtros.')}</section>`;
}
function lists(){const ls=state.lists.filter(l=>!filters.q||(l.name+' '+l.category).toLowerCase().includes(filters.q.toLowerCase()));return heading('Cultive novas conexões','Organize a prospecção ativa e acompanhe as respostas da comunidade.',button('Nova campanha','campaign','','secondary','mail')+button('Nova lista','list','','','plus'))+`<div class="filters"><div class="search">${icon('search')}<input id="search" type="search" aria-label="Buscar listas" placeholder="Buscar uma lista…" value="${esc(filters.q)}"></div><span class="toolbar-end muted" style="font-size:11px">${state.lists.length} listas · ${state.campaigns.length} campanhas realizadas</span></div><div class="lists-grid">${ls.map(l=>`<article class="panel list-card"><div class="flex between"><span class="list-icon">${icon('users')}</span>${badge(l.category,'gold')}</div><h2>${esc(l.name)}</h2><p>${esc(l.description)}</p><footer><small>${l.contacts.length} contatos · ${l.contacts.filter(id=>!state.contacts.find(c=>c.id===id)?.optOut).length} elegíveis</small>${button('Abrir lista','list-detail',l.id,'quiet','arrow')}</footer></article>`).join('')||empty('Nenhuma lista encontrada.')}</div><section class="panel" style="margin-top:26px"><div class="panel-header"><div><h2>Campanhas de relacionamento</h2><p>Mensagens e destinatários registrados na linha do tempo</p></div>${icon('mail')}</div>${state.campaigns.length?`<div class="table-wrap"><table><thead><tr><th>Assunto</th><th>Destinatários</th><th>Data</th><th></th></tr></thead><tbody>${state.campaigns.map(c=>`<tr><td>${esc(c.subject)}</td><td>${c.contacts.length} contatos</td><td>${time(c.at)}</td><td>${button('Ver mensagem','campaign-detail',c.id,'quiet')}</td></tr>`).join('')}</tbody></table></div>`:empty('Sua próxima mensagem pode iniciar uma bonita história. Crie uma campanha para começar.')}</section>`}
function paymentTable(ps,compact=false){return ps.length?`<div class="table-wrap"><table><thead><tr><th>Doador</th><th>Valor</th><th>${compact?'Modalidade':'Data / competência'}</th>${compact?'':'<th>Destinação</th>'}<th></th></tr></thead><tbody>${ps.map(p=>{const c=state.contacts.find(c=>c.id===p.contactId);return `<tr><td>${contactCell(c)}</td><td style="color:var(--dark);font-weight:600">${money(p.amount)}</td><td>${compact?badge(p.mode,p.mode==='Pontual'?'gold':''):date(p.date)+`<small style="display:block">${monthLabel(p.period)} · ${p.mode}</small>`}</td>${compact?'':`<td>${esc(p.destination)}</td>`}<td><button class="icon-button" data-action="receipt" data-id="${p.id}" title="Ver recibo" aria-label="Ver recibo ${p.receipt}">${icon('file')}</button></td></tr>`}).join('')}</tbody></table></div>`:empty('Nenhuma contribuição encontrada neste período.')}
function finance(){const ps=state.payments.filter(p=>(!filters.period||p.date.startsWith(filters.period))&&(!filters.mode||p.mode===filters.mode)&&(!filters.q||state.contacts.find(c=>c.id===p.contactId)?.name.toLowerCase().includes(filters.q.toLowerCase()))).sort((a,b)=>b.date.localeCompare(a.date)),pending=D.pending(state).filter(p=>(!filters.period||p.period===filters.period)&&(!filters.q||p.name.toLowerCase().includes(filters.q.toLowerCase()))&&(!filters.status||p.overdue));return heading('Contribuições que transformam','Recebimentos via Pix, baixas mensais e cuidado com cada contribuição.',button('Exportar','export-finance','','secondary','download')+button('Registrar doação','payment','','','plus'))+`<section class="metrics">${metric('Recebido neste mês',money(total(paymentsFor())),'Doações financeiras confirmadas','wallet')}${metric('Recorrentes neste mês',money(total(paymentsFor().filter(p=>p.mode==='Recorrente'))),'Compromissos que viram cuidado','heart')}${metric('Pontuais neste mês',money(total(paymentsFor().filter(p=>p.mode==='Pontual'))),'Gestos de generosidade','leaf')}${metric('Saldo pendente',money(total(D.pending(state))),D.pending(state).length+' competências abertas','clock',true)}</section><div class="tabs"><button class="tab ${financeTab==='payments'?'active':''}" data-action="finance-tab" data-id="payments">Recebimentos</button><button class="tab ${financeTab==='pending'?'active':''}" data-action="finance-tab" data-id="pending">Pendências mensais ${badge(D.pending(state).length,'gold')}</button></div><div class="filters"><div class="search">${icon('search')}<input id="search" type="search" placeholder="Buscar um doador…" aria-label="Buscar doador" value="${esc(filters.q)}"></div><input type="month" name="period" value="${esc(filters.period)}" aria-label="Mês de recebimento ou competência">${financeTab==='payments'?select('mode',['Recorrente','Pontual'],filters.mode,'Todas as modalidades'):select('status',[['overdue','Somente em atraso']],filters.status,'Todas as pendências')}${Object.values(filters).some(Boolean)?button('Limpar filtros','clear','','quiet'):''}</div><section class="panel">${financeTab==='payments'?paymentTable(ps):pending.length?`<div class="table-wrap"><table><thead><tr><th>Doador</th><th>Competência</th><th>Vencimento</th><th>Saldo a receber</th><th>Situação</th><th></th></tr></thead><tbody>${pending.map(p=>`<tr><td>${contactCell(state.contacts.find(c=>c.id===p.contactId))}</td><td>${monthLabel(p.period)}</td><td>${date(p.due)}</td><td>${money(p.amount)}</td><td>${badge(p.overdue?'Em atraso':'A vencer',p.overdue?'red':'gold')}</td><td>${button('Dar baixa','payment-pending',p.contactId+'|'+p.period,'secondary small','check')}</td></tr>`).join('')}</tbody></table></div>`:empty('Nenhuma pendência encontrada. Obrigado por cultivar esses laços.')}</section>`}
function reports(){const period=filters.period||D.month(),ps=paymentsFor(period).filter(p=>!filters.mode||p.mode===filters.mode).filter(p=>!filters.stage||String(state.contacts.find(c=>c.id===p.contactId)?.stage)===filters.stage),cs=state.contacts.filter(c=>D.month(c.created)===period&&(!filters.stage||String(c.stage)===filters.stage));return heading('O cuidado também se mede','Indicadores calculados a partir das contribuições e dos relacionamentos.',button('Exportar relatório','export-report','','secondary','download'))+`<div class="filters"><span class="filter-label">Período de análise</span><input type="month" name="period" value="${period}" aria-label="Período de análise">${select('mode',['Recorrente','Pontual'],filters.mode,'Todas as modalidades')}${select('stage',D.STAGES.map((s,i)=>[i,s]),filters.stage,'Todas as etapas')}</div><section class="metrics">${metric('Total arrecadado',money(total(ps)),ps.length+' lançamentos no período','wallet')}${metric('Doações recorrentes',money(total(ps.filter(p=>p.mode==='Recorrente'))),ps.filter(p=>p.mode==='Recorrente').length+' contribuições','heart')}${metric('Doações pontuais',money(total(ps.filter(p=>p.mode==='Pontual'))),ps.filter(p=>p.mode==='Pontual').length+' contribuições','leaf')}${metric('Conversão em doadores',(cs.filter(c=>c.plan&&c.plan.since<=period).length/Math.max(1,cs.length)*100).toFixed(1)+'%',cs.filter(c=>c.plan&&c.plan.since<=period).length+' doadores / '+cs.length+' contatos','chart',true)}</section><div class="report-grid"><section class="panel"><div class="panel-header"><div><h2>Recursos que chegam à comunidade</h2><p>Distribuição das doações por destinação</p></div></div><div class="panel-body">${D.DESTINATIONS.map(dest=>{const sum=total(ps.filter(p=>p.destination===dest));return `<div class="funnel-row"><div class="info">${dest}<div class="progress"><i style="width:${sum/Math.max(1,total(ps))*100}%"></i></div></div><strong style="font-size:13px">${money(sum)}</strong></div>`}).join('')}</div></section><section class="panel"><div class="panel-header"><div><h2>Conversão em cada etapa</h2><p>Contatos que alcançaram a etapa seguinte</p></div></div><div class="panel-body">${D.STAGES.map((stage,i)=>{const reached=cs.filter(c=>c.stage>=i||c.history.some(h=>h.action==='Etapa alterada'&&h.details.startsWith(stage)&&D.month(h.at)<=period)),converted=reached.filter(c=>i===3?c.plan&&c.plan.since<=period:c.stage>i||c.plan&&c.plan.since<=period||c.history.some(h=>h.action==='Etapa alterada'&&D.month(h.at)<=period&&D.STAGES.slice(i+1).some(t=>h.details.startsWith(t))));return `<div class="funnel-row"><div class="info">${esc(stage)}<small style="display:block;margin-top:5px">${converted.length} de ${reached.length} contatos${i===3?' tornaram-se doadores':' avançaram'}</small></div><strong>${(converted.length/Math.max(1,reached.length)*100).toFixed(0)}%</strong></div>`}).join('')}</div></section></div><section class="panel" style="margin-top:22px"><div class="panel-header"><div><h2>Contribuições do período</h2><p>Valores vinculados aos lançamentos financeiros</p></div><span class="badge">${monthLabel(period)}</span></div>${paymentTable(ps)}</section>`}
function users(){return heading('Pessoas que cuidam da nossa missão','Administre o acesso da equipe e os papéis de cada operador.',button('Novo usuário','user','','','plus'))+`<section class="panel"><div class="table-wrap"><table><thead><tr><th>Nome e e-mail</th><th>Perfil de acesso</th><th>Status</th><th></th></tr></thead><tbody>${state.users.map(u=>`<tr><td><div class="contact-cell">${avatar(u)}<div>${esc(u.name)}<small>${esc(u.email)}</small></div></div></td><td>${badge(u.role,u.role==='Administrador'?'gold':'')}</td><td>${badge(u.active?'Ativo':'Inativo',u.active?'':'gray')}</td><td>${button('Editar','user',u.id,'quiet','edit')}</td></tr>`).join('')}</tbody></table></div></section><div class="notice green" style="margin-top:22px">Administradores têm acesso completo. Operadores de captação cuidam dos contatos, das listas, dos relacionamentos e dos lançamentos de doações.</div>`}
function auditPage(){const entries=state.audit.filter(e=>!filters.q||(e.actorName+' '+e.action+' '+e.details).toLowerCase().includes(filters.q.toLowerCase()));return heading('Uma história que fica registrada','Rastreabilidade dos cadastros, relacionamentos e contribuições.')+`<div class="filters"><div class="search">${icon('search')}<input id="search" type="search" aria-label="Buscar na auditoria" placeholder="Buscar ação ou responsável…" value="${esc(filters.q)}"></div></div><section class="panel">${entries.length?`<div class="table-wrap"><table><thead><tr><th>Quando</th><th>Responsável</th><th>Ação</th><th>Detalhes</th></tr></thead><tbody>${entries.slice(0,100).map(e=>`<tr><td>${time(e.at)}</td><td>${esc(e.actorName)}</td><td>${esc(e.action)}</td><td style="max-width:380px;white-space:normal">${esc(e.details)}</td></tr>`).join('')}</tbody></table></div>`:empty('As ações da equipe aparecerão aqui.')}</section>`}
function renderLogin(){const token=new URLSearchParams(location.hash.slice(1)).get('redefinir');$('#app').innerHTML=`<div class="login"><section class="login-story">${brand()}<div><div class="eyebrow" style="margin-top:50px">Relacionamentos que transformam</div><h1>A esperança floresce quando cuidamos dos nossos laços.</h1><p>Um espaço para acolher, cultivar relacionamentos e acompanhar cada gesto de generosidade.</p><div class="art">${art()}</div></div><footer>Centro Espírita e Obras Sociais · Parnaíba, PI</footer></section><section class="login-content"><div class="login-form"><div class="eyebrow">Bem-vindo ao nosso espaço</div><h2>${token?'Uma nova senha':'Que bom ter você aqui.'}</h2><p>${token?'Escolha uma senha para voltar a cuidar dos nossos laços.':'Entre para acompanhar os relacionamentos e contribuições da nossa comunidade.'}</p><form id="auth-form"><div class="error" role="alert"></div>${token?field('Nova senha','password','','password','required minlength="8" autocomplete="new-password"')+field('Confirme a nova senha','confirm','','password','required minlength="8" autocomplete="new-password"'):field('Seu e-mail','email','','email','required autocomplete="username"')+field('Sua senha','password','','password','required autocomplete="current-password"')}<button class="btn" type="submit">${token?'Salvar nova senha':'Entrar no nosso espaço'} ${icon('arrow')}</button></form>${token?'':`<div style="text-align:right;margin-top:14px"><button class="text-link" data-action="recover">Esqueci minha senha</button></div><div class="demo"><p>Explore o protótipo com uma conta de demonstração.</p><div class="demo-buttons">${button('Administrador','demo','admin','secondary','shield')}${button('Operador','demo','operator','secondary','users')}</div><small style="display:block;margin-top:12px">Senha das contas de demonstração: <b>Esperanca@2026</b></small></div>`}<div class="login-bottom">Ambiente de demonstração · Dados fictícios</div></div></section></div>`;$('#auth-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,btn=$('button[type=submit]',f);btn.disabled=true;try{const d=Object.fromEntries(new FormData(f));if(token){const r=state.resets.find(r=>r.token===token&&!r.used&&r.expires>Date.now());if(!r)throw Error('Link de recuperação inválido ou expirado. Solicite outro.');if(d.password!==d.confirm)throw Error('As senhas precisam ser iguais.');const u=state.users.find(u=>u.id===r.userId);Object.assign(u,await credentials(d.password));r.used=true;D.audit(state,u,'Senha redefinida',null,'Recuperação de acesso');save();location.hash='';renderLogin();toast('Senha redefinida. Você já pode entrar.');return}if(Date.now()<lockUntil)throw Error('Aguarde um minuto antes de tentar novamente.');const u=state.users.find(u=>u.email.toLowerCase()===d.email.trim().toLowerCase()&&u.active);if(!u||await hashPassword(d.password,u.salt)!==u.passwordHash){loginAttempts++;if(loginAttempts>=5){lockUntil=Date.now()+60000;loginAttempts=0}throw Error('E-mail ou senha inválidos, ou usuário inativo.')}user=u;loginAttempts=0;lastActivity=Date.now();sessionStorage.setItem(SESSION,JSON.stringify({id:u.id,last:lastActivity}));page=u.role==='Administrador'?'dashboard':'funnel';D.audit(state,user,'Acesso ao sistema',null,'Sessão iniciada');D.reconcile(state,{id:'system',name:'Sistema'});save();render()}catch(err){$('.error',f).textContent=err.message;btn.disabled=false}}}
function bindPage(){const all=$('[data-action=select-filtered]');if(all){const eligible=visibleContacts().filter(emailEligible);all.indeterminate=!all.checked&&eligible.some(c=>selectedContacts.has(c.id))}const search=$('#search');if(search)search.addEventListener('input',e=>{filters.q=e.target.value;contactPage=1;const pos=e.target.selectionStart;$('#main').innerHTML=content()+pageFooter();bindPage();$('#search')?.focus();$('#search')?.setSelectionRange(pos,pos)});$$('.filters select,.filters input[type=month]').forEach(el=>el.onchange=()=>{filters[el.name]=el.value;contactPage=1;render()});$$('.card').forEach(el=>el.ondragstart=e=>{e.dataTransfer.setData('text/plain',el.dataset.contact);e.dataTransfer.effectAllowed='move'});$$('.column').forEach(el=>{el.ondragover=e=>{e.preventDefault();el.classList.add('over')};el.ondragleave=()=>el.classList.remove('over');el.ondrop=e=>{e.preventDefault();el.classList.remove('over');try{activeUser();D.move(state,user,e.dataTransfer.getData('text/plain'),Number(el.dataset.stage));save();render();toast('Etapa atualizada no histórico.')}catch(err){toast(err.message,'error')}}})}
let returnFocus;
function closeModal(){const m=$('#modal');if(m.open)m.close();m.innerHTML='';m.classList.remove('wide');returnFocus?.focus()}
function modal(title,body,footer='',wide=false){returnFocus=document.activeElement;const m=$('#modal');m.classList.toggle('wide',wide);m.innerHTML=`<div class="modal-head"><h2 id="modal-title">${title}</h2><button type="button" class="icon-button" data-action="close" aria-label="Fechar">${icon('close')}</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-foot">${footer}</div>`:''}`;if(!m.open)m.showModal();m.scrollTop=0}
function formModal(title,body,onSubmit,label='Salvar',wide=false,auth=false){modal(title,`<form id="modal-form"><div class="error" role="alert"></div>${body}<div class="modal-foot" style="margin:12px -28px -24px">${button('Cancelar','close')}<button type="submit" class="btn">${label} ${icon('check')}</button></div></form>`,'',wide);$('#modal-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,submit=$('[type=submit]',f);submit.disabled=true;try{if(!auth)activeUser();await onSubmit(Object.fromEntries(new FormData(f)),f)}catch(err){$('.error',f).textContent=err.message;submit.disabled=false}}}
function contactForm(id='',draft=null){const existing=state.contacts.find(c=>c.id===id),c=draft||existing||{name:'',email:'',phone:'',type:'PF',document:'',origin:'Indicação',funnel:'Inbound',stage:0,owner:user.id};formModal(existing?'Editar relacionamento':'Um novo relacionamento',`<div class="step-label">1 de 2 · Conhecer a pessoa</div><div class="form-grid">${field('Nome completo / razão social *','name',c.name,'text','required maxlength="120"')}${selectField('Tipo de pessoa','type',[['PF','Pessoa física'],['PJ','Pessoa jurídica']],c.type)}${field('E-mail','email',c.email,'email','maxlength="150"')}${field('Telefone / WhatsApp','phone',c.phone,'tel','maxlength="16" placeholder="(86) 99999-9999"')}${field('CPF / CNPJ (opcional)','document',c.document,'text','inputmode="numeric" maxlength="18"')}<div class="full"><small>Informe pelo menos um e-mail ou telefone para mantermos esse laço.</small></div></div>`,d=>{const merged={...c,...d};D.validateContact(merged,state.contacts,id);contactStepTwo(id,merged)},'Continuar');const phone=$f('[name=phone]'),doc=$f('[name=document]');phone.oninput=()=>{let n=phone.value.replace(/\D/g,'').slice(0,11);phone.value=n.replace(/^(\d{2})(\d)/,'($1) $2').replace(/(\d{4,5})(\d{4})$/,'$1-$2')};doc.oninput=()=>{const n=doc.value.replace(/\D/g,'').slice(0,$f('[name=type]').value==='PF'?11:14);doc.value=$f('[name=type]').value==='PF'?n.replace(/^(\d{3})(\d)/,'$1.$2').replace(/^(\d{3})\.(\d{3})(\d)/,'$1.$2.$3').replace(/(\d{3})(\d{2})$/,'$1-$2'):n.replace(/^(\d{2})(\d)/,'$1.$2').replace(/^(\d{2})\.(\d{3})(\d)/,'$1.$2.$3').replace(/(\d{3})(\d{4})/,'$1/$2').replace(/(\d{4})(\d{2})$/,'$1-$2')};$f('[name=type]').onchange=()=>doc.oninput()}
function contactStepTwo(id,c){formModal('Onde começa esse caminho?',`<div class="step-label">2 de 2 · Origem e relacionamento</div><div class="notice green">${esc(c.name)} · ${esc(c.email||c.phone)}</div><div class="form-grid">${selectField('Canal de origem','origin',D.ORIGINS,c.origin)}${selectField('Funil de destino','funnel',['Inbound','Outbound'],c.funnel)}${selectField('Etapa inicial','stage',D.STAGES.map((s,i)=>[i,s]),c.stage)}${user.role==='Administrador'?selectField('Operador responsável','owner',state.users.filter(u=>u.active).map(u=>[u.id,u.name]),c.owner):''}</div>${button('Voltar aos dados','contact-back',id,'quiet')}`,d=>{const merged={...c,...d,stage:Number(d.stage),owner:d.owner||c.owner};D.validateContact(merged,state.contacts,id);const existing=state.contacts.find(c=>c.id===id);if(existing){const oldStage=existing.stage;Object.assign(existing,merged,{stage:oldStage});D.move(state,user,id,merged.stage);D.audit(state,user,'Cadastro atualizado',id)}else{merged.id=D.uid();merged.created=new Date().toISOString();merged.history=[];merged.optOut=false;state.contacts.unshift(merged);D.audit(state,user,'Contato cadastrado',merged.id,merged.origin+' · '+merged.funnel)}save();closeModal();render();profile(existing?.id||merged.id);toast('Relacionamento salvo com carinho.')} ,'Salvar contato');$('[data-action=contact-back]').onclick=e=>{e.stopPropagation();contactForm(id,c)}}
function profile(id){const c=state.contacts.find(c=>c.id===id);if(!c)throw Error('Contato não encontrado.');const ps=state.payments.filter(p=>p.contactId===id);modal('Ficha de relacionamento',`<div class="profile-hero">${avatar(c)}<div><h2>${esc(c.name)}</h2><p style="margin-top:7px">${statusBadge(c)} ${badge(c.type,'gold')} ${c.optOut?badge('Descadastrado de e-mails','gray'):''}</p></div></div><div class="profile-grid"><div><dl class="details"><div><dt>E-mail</dt><dd>${esc(c.email||'Não informado')}</dd></div><div><dt>Telefone</dt><dd>${esc(c.phone||'Não informado')}</dd></div><div><dt>CPF / CNPJ</dt><dd>${esc(c.document||'Não informado')}</dd></div><div><dt>Origem</dt><dd>${esc(c.origin)} · ${c.funnel}</dd></div><div><dt>Responsável</dt><dd>${esc(state.users.find(u=>u.id===c.owner)?.name||'—')}</dd></div><div><dt>Desde</dt><dd>${date(c.created)}</dd></div></dl><div class="notice green"><small>Etapa atual</small><p>${D.STAGES[c.stage]}</p>${c.plan?`<p style="margin-top:10px"><b>${money(c.plan.amount)}</b> · ${c.plan.mode}${c.plan.due?' · Dia '+c.plan.due:''}</p>`:''}</div><div class="profile-actions">${button('Editar','contact',id,'secondary small','edit')}${!c.plan?button('Mover etapa','move',id,'secondary small','funnel')+button('Converter em doador','convert',id,'small','heart'):button('Registrar doação','payment',id,'small','plus')+button('Alterar status','donor-status',id,'secondary small')}${button('Registrar interação','interaction',id,'secondary small','plus')}${button('Registrar resposta','response',id,'secondary small','mail')}${c.plan?button('Comprovante de adesão','adherence',id,'quiet small','file'):''}${!c.optOut&&c.email?button('Enviar mensagem','contact-mail',id,'quiet small','mail'):''}${user.role==='Administrador'?button('Excluir contato','delete-contact',id,'danger small'):''}</div>${ps.length?`<h3 style="margin:22px 0 8px">Contribuições · ${money(total(ps))}</h3>${ps.slice(0,4).map(p=>`<div class="list-row"><div><p>${money(p.amount)}</p><small>${date(p.date)} · ${monthLabel(p.period)}</small></div><button class="icon-button right" data-action="receipt" data-id="${p.id}" aria-label="Ver recibo">${icon('file')}</button></div>`).join('')}`:''}</div><div><div class="flex between" style="margin-bottom:22px"><h3>Uma história de relacionamento</h3><small>${c.history.length} registros</small></div><div class="timeline">${c.history.map(e=>`<article class="event"><h3>${esc(e.action)}</h3><p>${esc(e.details)}</p><small>${time(e.at)} · ${esc(e.actorName)}</small></article>`).join('')}</div></div></div>`,'',true)}
function moveForm(id){const c=state.contacts.find(c=>c.id===id);formModal('Um novo passo no relacionamento',`<p class="muted" style="margin-bottom:20px">${esc(c.name)}</p>${selectField('Próxima etapa','stage',D.STAGES.map((s,i)=>[i,s]),c.stage)}<div class="field"><label for="f-note">Anotações da mudança</label><textarea id="f-note" name="note" placeholder="O que motivou este novo passo?" maxlength="1500"></textarea></div>`,d=>{D.move(state,user,id,Number(d.stage),d.note);save();closeModal();render();toast('Etapa atualizada e registrada no histórico.')},'Atualizar etapa')}
function convertForm(id){const c=state.contacts.find(c=>c.id===id);formModal('Um novo gesto de generosidade',`<div class="notice green">${esc(c.name)} passará a fazer parte da nossa rede de doadores.</div>${selectField('Modalidade de contribuição','mode',['Recorrente','Pontual'],'Recorrente')}${field('Valor compromissado (R$) *','amount',100,'number','required min="0.01" max="999999999" step="0.01"')}${field('Dia do vencimento mensal *','due',10,'number','required min="1" max="28" step="1"')}<small>O comprovante de adesão será gerado após a conversão.</small>`,d=>{D.convert(state,user,id,{mode:d.mode,amount:Number(d.amount),due:Number(d.due)});save();closeModal();render();adherence(id);toast('Contato convertido em doador ativo.')},'Confirmar adesão');$f('[name=mode]').onchange=()=>{const input=$f('[name=due]');input.closest('.field').hidden=$f('[name=mode]').value==='Pontual';input.required=$f('[name=mode]').value==='Recorrente'}}
function adherence(id){const c=state.contacts.find(c=>c.id===id);modal('Comprovante de adesão',`<div class="receipt">${brand()}<div class="eyebrow">Cuidar, contribuir, transformar</div><h2>Compromisso de contribuição</h2><p>${esc(c.name)} · ${esc(c.email||c.phone)}</p><strong class="amount">${money(c.plan.amount)}</strong><dl class="details"><div><dt>Modalidade</dt><dd>${c.plan.mode}</dd></div><div><dt>Adesão</dt><dd>${monthLabel(c.plan.since)}</dd></div><div><dt>Vencimento</dt><dd>${c.plan.due?'Todo dia '+c.plan.due:'Contribuição única'}</dd></div><div><dt>Situação</dt><dd>${c.plan.status}</dd></div></dl><p>Obrigado por caminhar com a Luz da Esperança.</p><small>Comprovante de adesão · Não representa confirmação de pagamento.</small></div>`,button('Fechar','close')+button('Imprimir / salvar PDF','print','','','download'))}
function interactionForm(id){formModal('Cultive esse relacionamento',`${selectField('Como foi o contato?','channel',['Telefone','WhatsApp','Reunião','E-mail'],'WhatsApp')}${field('Data e hora do contato','date',new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16),'datetime-local','required')}<div class="field"><label for="f-summary">Resumo da conversa *</label><textarea id="f-summary" name="summary" required maxlength="3000" placeholder="Conte o que foi conversado e os próximos passos."></textarea></div><small>Este registro preserva o histórico e identifica o operador responsável.</small>`,d=>{if(new Date(d.date)>new Date())throw Error('A data do contato não pode ser futura.');if(!d.summary.trim())throw Error('Informe o resumo da conversa.');D.audit(state,user,'Contato por '+d.channel,id,d.summary+'\nData do contato: '+time(d.date));save();closeModal();render();profile(id);toast('Interação registrada no histórico.')},'Registrar interação')}
function responseForm(id){formModal('Escutar também faz parte',`${selectField('Classificação da resposta','classification',['Positiva','Negativa','Pedido de descadastro'],'Positiva')}<div class="field"><label for="f-message">Conteúdo da resposta *</label><textarea id="f-message" name="message" required maxlength="3000" placeholder="Registre a resposta recebida."></textarea></div>`,d=>{if(!d.message.trim())throw Error('Informe o conteúdo da resposta.');const c=state.contacts.find(c=>c.id===id);if(d.classification==='Pedido de descadastro')c.optOut=true;D.audit(state,user,'Resposta de e-mail: '+d.classification,id,d.message);save();closeModal();render();profile(id);toast(d.classification==='Pedido de descadastro'?'Descadastro registrado. Novos envios serão bloqueados.':'Resposta registrada.')},'Registrar resposta')}
function statusForm(id){const c=state.contacts.find(c=>c.id===id);formModal('Cuidar do ciclo do doador',`${selectField('Novo status','status',['Ativo','Inadimplente','Pausado','Cancelado'],c.plan.status)}${field('Data do evento','date',D.today(),'date','required')}<div class="field"><label for="f-reason">Motivo da alteração *</label><textarea id="f-reason" name="reason" required maxlength="2000"></textarea></div>`,d=>{if(d.date>D.today())throw Error('A data não pode ser futura.');if(!d.reason.trim())throw Error('Informe o motivo.');c.plan.status=d.status;D.audit(state,user,'Status do doador alterado',id,d.status+' · '+d.reason+' · '+date(d.date));save();closeModal();render();profile(id);toast('Status atualizado e histórico preservado.')},'Atualizar status')}
function paymentForm(id='',period='',draft=null){const c=state.contacts.find(c=>c.id===id),pending=D.pending(state).find(p=>p.contactId===id&&p.period===period),d=draft||{contactId:id,amount:pending?.amount||c?.plan?.amount||'',date:D.today(),period:period||D.month(),destination:'Obras sociais'};formModal('Um gesto que faz a diferença',`<div class="step-label">1 de 2 · Contribuição financeira</div><div class="form-grid">${selectField('Doador *','contactId',state.contacts.filter(c=>c.plan).map(c=>[c.id,c.name]),d.contactId,'Selecione um doador')}${field('Valor recebido (R$) *','amount',d.amount,'number','required min="0.01" max="999999999" step="0.01"')}${field('Data do pagamento *','date',d.date,'date','required max="'+D.today()+'"')}${field('Competência mensal *','period',d.period,'month','required')}${selectField('Destinação do recurso','destination',D.DESTINATIONS,d.destination)}<div class="full"><small>Registre apenas contribuições financeiras em reais. A baixa fica vinculada ao doador e à competência.</small></div></div>`,data=>{if(!data.contactId)throw Error('Selecione um doador.');if(Number(data.amount)<=0)throw Error('Informe um valor maior que zero.');paymentStepTwo({...data,amount:Number(data.amount)})},'Continuar');const pick=$f('[name=contactId]');pick.required=true;pick.onchange=()=>{const donor=state.contacts.find(c=>c.id===pick.value);if(donor){$f('[name=amount]').value=donor.plan.amount;$f('[name=period]').min=donor.plan.since;$f('[name=period]').closest('.field').hidden=donor.plan.mode==='Pontual';$f('[name=period]').required=donor.plan.mode==='Recorrente'}};if(c){$f('[name=period]').min=c.plan.since;$f('[name=period]').closest('.field').hidden=c.plan.mode==='Pontual';$f('[name=period]').required=c.plan.mode==='Recorrente'}}
function fileData(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve({name:file.name,type:file.type,data:r.result});r.onerror=()=>reject(Error('Não foi possível ler o arquivo.'));r.readAsDataURL(file)})}
function paymentStepTwo(d){formModal('Vincule o comprovante',`<div class="step-label">2 de 2 · Identificação do recebimento</div><div class="notice green">${esc(state.contacts.find(c=>c.id===d.contactId).name)} · <b>${money(d.amount)}</b> · ${date(d.date)}</div>${field('Código / referência Pix','pix','','text','maxlength="180" placeholder="Identificador do recebimento"')}${field('Comprovante (opcional)','attachment','','file','accept="image/png,image/jpeg,application/pdf"')}<small>Informe a referência Pix ou anexe um comprovante (PNG, JPG ou PDF, até 2 MB).</small><div style="margin-top:14px">${button('Voltar à contribuição','payment-back','','quiet')}</div>`,async(data,f)=>{const file=$f('[name=attachment]',f).files[0];if(file&&(file.size>2*1024*1024||!['image/png','image/jpeg','application/pdf'].includes(file.type)))throw Error('Anexe PNG, JPG ou PDF de até 2 MB.');const attachment=file?await fileData(file):null,p=D.payment(state,user,{...d,pix:data.pix,attachment});save();closeModal();render();receipt(p.id);toast('Doação registrada. Pendência e indicadores atualizados.')},'Confirmar recebimento');$('[data-action=payment-back]').onclick=e=>{e.stopPropagation();paymentForm(d.contactId,d.period,d)}}
function receipt(id){const p=state.payments.find(p=>p.id===id),c=state.contacts.find(c=>c.id===p.contactId);modal('Recibo de contribuição',`<div class="receipt">${brand()}<div class="eyebrow">${p.receipt}</div><h2>Obrigado por espalhar esperança.</h2><p>Recebemos de <b>${esc(c.name)}</b> uma contribuição financeira para apoiar nossas obras sociais.</p><strong class="amount">${money(p.amount)}</strong><dl class="details"><div><dt>Data do pagamento</dt><dd>${date(p.date)}</dd></div><div><dt>Competência</dt><dd>${monthLabel(p.period)}</dd></div><div><dt>Modalidade</dt><dd>${p.mode}</dd></div><div><dt>Destinação</dt><dd>${esc(p.destination)}</dd></div><div><dt>Referência Pix</dt><dd>${esc(p.pix||'Comprovante anexo')}</dd></div><div><dt>Responsável pelo registro</dt><dd>${esc(p.actorName)} · ${time(p.at)}</dd></div></dl>${p.attachment?button('Baixar comprovante · '+esc(p.attachment.name),'attachment',p.id,'secondary small','download'):''}<p>Centro Espírita e Obras Sociais Luz da Esperança<br>Parnaíba, PI</p><small>Recibo emitido no ambiente de demonstração com dados fictícios.</small></div>`,button('Fechar','close')+button('Imprimir / salvar PDF','print','','','download'))}
function listForm(id=''){const l=state.lists.find(l=>l.id===id);formModal(l?'Editar lista':'Uma nova rede de conexões',`${field('Nome da lista *','name',l?.name||'','text','required maxlength="120"')}${field('Categoria dos contatos *','category',l?.category||'','text','required maxlength="80"')}<div class="field"><label for="f-description">Descrição da lista</label><textarea id="f-description" name="description" maxlength="1500">${esc(l?.description||'')}</textarea></div>`,d=>{if(!d.name.trim()||!d.category.trim())throw Error('Informe nome e categoria.');if(l)Object.assign(l,d);else state.lists.unshift({...d,id:D.uid(),contacts:[],imports:[]});D.audit(state,user,l?'Lista atualizada':'Lista criada',null,d.name);save();closeModal();render();toast('Lista salva.')},'Salvar lista')}
function listDetail(id){const l=state.lists.find(l=>l.id===id);modal(esc(l.name),`<p class="muted" style="margin-bottom:20px">${esc(l.description)}</p><div class="flex" style="flex-wrap:wrap;margin-bottom:20px">${button('Importar CSV / Excel','import',id,'','upload')}${button('Adicionar contatos','list-contacts',id,'secondary','plus')}${button('Criar campanha','campaign',id,'secondary','mail')}${button('Editar lista','list',id,'quiet','edit')}</div><div class="table-wrap"><table><thead><tr><th>Contato</th><th>Envios</th><th></th></tr></thead><tbody>${l.contacts.map(id=>state.contacts.find(c=>c.id===id)).filter(Boolean).map(c=>`<tr><td>${contactCell(c)}</td><td>${badge(c.optOut?'Descadastrado':c.email?'Elegível':'Sem e-mail',c.optOut?'gray':'')}</td><td><button class="icon-button" data-action="remove-list-contact" data-id="${l.id+'|'+c.id}" aria-label="Remover da lista">${icon('close')}</button></td></tr>`).join('')}</tbody></table></div>${!l.contacts.length?empty('Importe um arquivo ou adicione contatos da sua rede.') :''}${l.imports.length?`<h3 style="margin:22px 0 10px">Última importação</h3><div class="notice green">${l.imports[0].imported} importados · ${l.imports[0].duplicates} duplicados · ${l.imports[0].invalid} inválidos</div>${l.imports[0].rows.length?`<details><summary>Ver registros descartados</summary><p style="font-size:11px;margin-top:10px">${l.imports[0].rows.map(esc).join('<br>')}</p></details>`:''}`:''}`,'',true)}
function listContacts(id){const l=state.lists.find(l=>l.id===id);formModal('Adicionar à nossa rede',`<p class="muted" style="margin-bottom:15px">${esc(l.name)}</p><div class="check-list">${state.contacts.filter(c=>!l.contacts.includes(c.id)).map(c=>`<label><input type="checkbox" name="contacts" value="${c.id}">${esc(c.name)} <small>${esc(c.email)}</small></label>`).join('')||empty('Todos os contatos já estão nesta lista.')}</div>`,(d,f)=>{const ids=new FormData(f).getAll('contacts');if(!ids.length)throw Error('Selecione pelo menos um contato.');l.contacts.push(...ids);D.audit(state,user,'Contatos adicionados à lista',null,l.name+' · '+ids.length);save();closeModal();render();listDetail(id)},'Adicionar contatos')}
async function excelRows(file){const buf=await file.arrayBuffer(),v=new DataView(buf),bytes=new Uint8Array(buf),files={};let eocd=-1;for(let i=v.byteLength-22;i>=Math.max(0,v.byteLength-65557);i--){if(v.getUint32(i,true)===0x06054b50){eocd=i;break}}if(eocd<0)throw Error('Excel inválido. Use .xlsx ou salve como CSV.');let pos=v.getUint32(eocd+16,true),count=v.getUint16(eocd+10,true),budget=0;for(let i=0;i<count;i++){if(v.getUint32(pos,true)!==0x02014b50)throw Error('Arquivo Excel inválido.');const method=v.getUint16(pos+10,true),size=v.getUint32(pos+20,true),rawSize=v.getUint32(pos+24,true),nameLen=v.getUint16(pos+28,true),extraLen=v.getUint16(pos+30,true),commentLen=v.getUint16(pos+32,true),offset=v.getUint32(pos+42,true),name=new TextDecoder().decode(bytes.slice(pos+46,pos+46+nameLen));pos+=46+nameLen+extraLen+commentLen;if(!/^xl\/(sharedStrings\.xml|worksheets\/sheet\d+\.xml)$/.test(name))continue;budget+=rawSize;if(budget>20*1024*1024)throw Error('Planilha muito grande. Importe até 20 MB de conteúdo descompactado.');const start=offset+30+v.getUint16(offset+26,true)+v.getUint16(offset+28,true),compressed=bytes.slice(start,start+size);let out;if(method===0)out=compressed;else if(method===8){try{out=new Uint8Array(await new Response(new Blob([compressed]).stream().pipeThrough(new DecompressionStream('deflate-raw'))).arrayBuffer())}catch{throw Error('Este navegador não lê o Excel comprimido. Use um navegador atualizado ou salve como CSV.')}}else throw Error('Compressão Excel não suportada. Salve como CSV.');files[name]=new TextDecoder().decode(out)}const parser=new DOMParser(),strings=files['xl/sharedStrings.xml']?[...parser.parseFromString(files['xl/sharedStrings.xml'],'application/xml').getElementsByTagName('si')].map(si=>[...si.getElementsByTagName('t')].map(t=>t.textContent).join('')):[];const sheet=Object.keys(files).filter(n=>n.includes('worksheets/')).sort()[0];if(!sheet)throw Error('Nenhuma planilha encontrada.');const xml=parser.parseFromString(files[sheet],'application/xml');if(xml.querySelector('parsererror'))throw Error('Planilha inválida.');return [...xml.getElementsByTagName('row')].map(row=>{const result=[];for(const c of row.getElementsByTagName('c')){const ref=c.getAttribute('r')||'A',col=[...ref.replace(/\d/g,'')].reduce((n,ch)=>n*26+ch.charCodeAt(0)-64,0)-1,type=c.getAttribute('t'),val=c.getElementsByTagName('v')[0]?.textContent||'';result[col]=type==='s'?strings[Number(val)]||'':type==='inlineStr'?[...c.getElementsByTagName('t')].map(t=>t.textContent).join(''):val}return result})}
function importForm(id){formModal('Novos laços para a nossa lista',`<div class="notice green">Importe CSV ou Excel (.xlsx) com as colunas <b>nome</b>, <b>email</b> e, opcionalmente, <b>telefone</b>. E-mails inválidos e duplicados serão descartados.</div>${field('Arquivo de contatos *','file','','file','required accept=".csv,.xlsx"')}${button('Baixar modelo CSV','csv-template','','quiet','download')}<small style="display:block;margin-top:12px">Até 5 MB por arquivo. O relatório da importação fica disponível na lista.</small>`,async(d,f)=>{const file=$('[name=file]',f).files[0];if(file.size>5*1024*1024)throw Error('O arquivo deve ter até 5 MB.');let rows;if(/\.xlsx$/i.test(file.name))rows=await excelRows(file);else if(/\.csv$/i.test(file.name))rows=D.parseCSV(await file.text());else throw Error('Use CSV ou Excel .xlsx.');if(rows.length>10001)throw Error('Importe até 10.000 contatos por arquivo.');const l=state.lists.find(l=>l.id===id),r=D.importRows(state,user,l,rows);save();closeModal();render();listDetail(id);toast(r.imported+' contatos importados · '+r.duplicates+' duplicados · '+r.invalid+' inválidos')},'Importar contatos')}
function campaignForm(listId='',contactId=''){if(!state.lists.length&&!contactId)throw Error('Crie uma lista de contatos antes da campanha.');formModal('Uma mensagem pode aproximar',`${contactId?`<div class="notice green">Para ${esc(state.contacts.find(c=>c.id===contactId).name)}</div>`:selectField('Lista de destinatários *','listId',state.lists.map(l=>[l.id,l.name]),listId||state.lists[0]?.id)}${field('Assunto da mensagem *','subject','','text','required maxlength="180"')}<div class="field"><label for="f-body">Mensagem *</label><textarea id="f-body" name="body" required maxlength="10000" rows="6" placeholder="Olá! Queremos compartilhar um pouco do que estamos construindo juntos…"></textarea></div><small>Contatos descadastrados ou sem e-mail ficam fora do envio.</small>`,d=>{const ids=contactId?[contactId]:state.lists.find(l=>l.id===d.listId).contacts;const eligible=ids.filter(id=>{const c=state.contacts.find(c=>c.id===id);return c?.email&&!c.optOut});if(!eligible.length)throw Error('Nenhum destinatário elegível nesta lista.');modal('Revise a mensagem',`<div class="notice green">${eligible.length} destinatário(s) elegível(is) · ${ids.length-eligible.length} excluído(s)</div><h3 style="margin-bottom:15px">${esc(d.subject)}</h3><div class="campaign-preview">${esc(d.body)}</div>`,button('Voltar','campaign-back')+button('Confirmar envio','campaign-send','','','mail'));$('[data-action=campaign-send]').onclick=e=>{e.stopPropagation();try{activeUser();const n=D.send(state,user,ids,d.subject,d.body);save();closeModal();render();toast(n+' mensagens registradas nas linhas do tempo.')}catch(err){toast(err.message,'error')}};$('[data-action=campaign-back]').onclick=e=>{e.stopPropagation();campaignForm(d.listId,contactId);$('[name=subject]').value=d.subject;$('[name=body]').value=d.body}},'Revisar mensagem')}
function userForm(id=''){admin();const u=state.users.find(u=>u.id===id);formModal(u?'Editar acesso':'Uma nova pessoa na equipe',`<div class="form-grid">${field('Nome completo *','name',u?.name||'','text','required maxlength="100"')}${field('E-mail de acesso *','email',u?.email||'','email','required maxlength="150"')}${selectField('Perfil de acesso','role',['Administrador','Operador de Captação'],u?.role||'Operador de Captação')}${selectField('Status','active',[['yes','Ativo'],['no','Inativo']],u?.active===false?'no':'yes')}${field(u?'Nova senha (opcional)':'Senha inicial *','password','','password',(u?'':'required ')+'minlength="8" autocomplete="new-password"')}<small>Use pelo menos 8 caracteres. Senhas são armazenadas por hash.</small></div>`,async d=>{admin();if(state.users.some(x=>x.id!==id&&x.email.toLowerCase()===d.email.toLowerCase()))throw Error('Este e-mail já possui acesso.');if(u?.id===user.id&&(d.role!=='Administrador'||d.active==='no'))throw Error('Você não pode remover seu próprio acesso administrativo.');if(u?.role==='Administrador'&&(d.role!=='Administrador'||d.active==='no')&&state.users.filter(x=>x.role==='Administrador'&&x.active&&x.id!==id).length===0)throw Error('Mantenha pelo menos um administrador ativo.');const update={name:d.name.trim(),email:d.email.trim(),role:d.role,active:d.active==='yes'};if(d.password)Object.assign(update,await credentials(d.password));if(u)Object.assign(u,update);else state.users.push({...update,id:D.uid()});D.audit(state,user,u?'Usuário atualizado':'Usuário cadastrado',null,d.name+' · '+d.role);save();closeModal();render();toast('Acesso da equipe atualizado.')},'Salvar acesso')}
function recover(){formModal('Vamos recuperar seu acesso',`<p class="muted" style="margin-bottom:20px">Informe o e-mail cadastrado para receber as instruções.</p>${field('E-mail de recuperação','email','','email','required')}`,d=>{const u=state.users.find(u=>u.email.toLowerCase()===d.email.trim().toLowerCase()&&u.active);if(!u){modal('Confira sua caixa de entrada','<p>Se o e-mail estiver cadastrado, você receberá as instruções de recuperação.</p>',button('Voltar ao acesso','close'));return}const token=D.uid();state.resets.push({token,userId:u.id,expires:Date.now()+15*60*1000,used:false});save();modal('Instruções de recuperação',`<div class="notice green">As instruções foram preparadas para ${esc(u.email)}.</div><p style="margin-bottom:16px">No protótipo, a entrega do e-mail é simulada. Use o link abaixo para testar a redefinição.</p><div class="campaign-preview">Olá, ${esc(u.name.split(' ')[0])}!<br>Você solicitou uma nova senha. Este link é válido por 15 minutos.</div><a class="btn" style="margin-top:20px" href="#redefinir=${token}" data-action="reset-link">Criar nova senha ${icon('arrow')}</a>`,button('Fechar','close'))},'Enviar instruções',false,true)}
function tasks(){modal('Cultivar nossos relacionamentos',state.tasks.filter(t=>!t.done).map(t=>`<div class="list-row"><div><h3>${esc(t.text)}</h3><small>${date(t.at)} · Reengajamento</small></div><div class="right flex">${button('Abrir contato','profile',t.contactId,'secondary small')}<button class="icon-button" data-action="task-done" data-id="${t.id}" aria-label="Concluir ação">${icon('check')}</button></div></div>`).join('')||empty('Nenhuma ação pendente. Os laços estão sendo bem cuidados.'))}
function download(name,data,type='text/csv;charset=utf-8'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([data],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function csv(rows){return '\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"').join(';')).join('\r\n')}
function exportContacts(){const cs=filterContacts().filter(c=>page==='donors'?c.plan:tab==='leads'?!c.plan:tab==='donors'?c.plan:true);download('relacionamentos-luz.csv',csv([['Nome','Email','Telefone','Tipo','Origem','Funil','Etapa','Status'],...cs.map(c=>[c.name,c.email,c.phone,c.type,c.origin,c.funnel,D.STAGES[c.stage],c.plan?.status||'Prospect'])]));toast('Relacionamentos exportados.')}
function exportFinance(report=false){if(report)admin();if(!report&&financeTab==='pending'){const ps=D.pending(state).filter(p=>(!filters.period||p.period===filters.period)&&(!filters.q||p.name.toLowerCase().includes(filters.q.toLowerCase()))&&(!filters.status||p.overdue));download('pendencias-luz.csv',csv([['Doador','Competencia','Vencimento','Saldo','Situacao'],...ps.map(p=>[p.name,p.period,p.due,p.amount,p.overdue?'Em atraso':'A vencer'])]));return}const ps=state.payments.filter(p=>(!filters.period?p.date.startsWith(report?D.month():''):p.date.startsWith(filters.period))&&(!filters.mode||p.mode===filters.mode)&&(!filters.stage||String(state.contacts.find(c=>c.id===p.contactId)?.stage)===filters.stage)&&(!filters.q||state.contacts.find(c=>c.id===p.contactId)?.name.toLowerCase().includes(filters.q.toLowerCase())));download('contribuicoes-luz.csv',csv([['Recibo','Doador','Valor R$','Pagamento','Competencia','Modalidade','Destinacao','Pix','Operador'],...ps.map(p=>[p.receipt,state.contacts.find(c=>c.id===p.contactId).name,p.amount,p.date,p.period,p.mode,p.destination,p.pix,p.actorName])]));toast('Contribuições exportadas.')}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,id=b.dataset.id||'';try{if(!['demo','recover','close','reset-link'].includes(a))activeUser();switch(a){case'demo':{const u=state.users.find(u=>u.id===id);$('[name=email]').value=u.email;$('[name=password]').value='Esperanca@2026';$('#auth-form').requestSubmit();break}case'nav':navigate(id);break;case'menu':$('.sidebar').classList.toggle('open');break;case'logout':D.audit(state,user,'Saída do sistema',null);save();logout();break;case'close':closeModal();break;case'profile':profile(id);break;case'contact':contactForm(id);break;case'move':moveForm(id);break;case'convert':convertForm(id);break;case'adherence':adherence(id);break;case'interaction':interactionForm(id);break;case'response':responseForm(id);break;case'donor-status':statusForm(id);break;case'payment':paymentForm(id);break;case'payment-pending':{const[c,p]=id.split('|');paymentForm(c,p);break}case'receipt':receipt(id);break;case'print':window.print();break;case'attachment':{const p=state.payments.find(p=>p.id===id);const link=document.createElement('a');link.href=p.attachment.data;link.download=p.attachment.name;link.click();break}case'funnel-view':funnelView=id;render();break;
case'funnel-stage':funnelMobileStage=Number(id);render();break;
case'select-contact':if(emailEligible(state.contacts.find(c=>c.id===id))){if(b.checked)selectedContacts.add(id);else selectedContacts.delete(id)}render();$('[data-action=select-contact][data-id="'+id+'"]')?.focus({preventScroll:true});break;
case'select-filtered':{const eligible=visibleContacts().filter(emailEligible);eligible.forEach(c=>b.checked?selectedContacts.add(c.id):selectedContacts.delete(c.id));render();$('[data-action=select-filtered]')?.focus({preventScroll:true});break}
case'clear-selection':selectedContacts.clear();render();break;
case'bulk-email':bulkEmailForm();break;
case'email-pick':if(emailEligible(state.contacts.find(c=>c.id===id))){if(b.checked)selectedContacts.add(id);else selectedContacts.delete(id)}updateEmailRecipients();break;
case'email-select-all':recipientMatches().filter(emailEligible).forEach(c=>b.checked?selectedContacts.add(c.id):selectedContacts.delete(c.id));updateEmailRecipients();break;
case'email-clear':selectedContacts.clear();updateEmailRecipients();break;
case'contact-tab':tab=id;contactPage=1;render();break;case'finance-tab':financeTab=id;filters.mode='';filters.status='';render();break;case'clear':filters={q:'',origin:'',owner:'',period:'',funnel:'',status:'',mode:'',stage:''};render();break;case'prev':contactPage--;render();break;case'next':contactPage++;render();break;case'list':listForm(id);break;case'list-detail':listDetail(id);break;case'list-contacts':listContacts(id);break;case'import':importForm(id);break;case'csv-template':download('modelo-contatos-luz.csv',csv([['nome','email','telefone'],['Novo Contato','novo@exemplo.com','86999990000']]));break;case'campaign':campaignForm(id);break;case'contact-mail':campaignForm('',id);break;case'campaign-detail':{const c=state.campaigns.find(c=>c.id===id);modal(esc(c.subject),`<p class="muted" style="margin-bottom:18px">${time(c.at)} · ${c.contacts.length} destinatários</p><div class="campaign-preview">${esc(c.body)}</div><h3 style="margin:22px 0 10px">Destinatários</h3><p style="font-size:12px">${c.contacts.map(id=>esc(state.contacts.find(c=>c.id===id)?.name||'Contato removido')).join(', ')}</p>`);break}case'remove-list-contact':{const[l,c]=id.split('|'),list=state.lists.find(x=>x.id===l);list.contacts=list.contacts.filter(x=>x!==c);D.audit(state,user,'Contato removido da lista',c,list.name);save();render();listDetail(l);break}case'user':userForm(id);break;case'recover':recover();break;case'reset-link':closeModal();setTimeout(()=>{user=null;sessionStorage.removeItem(SESSION);render()},0);break;case'tasks':tasks();break;case'task-done':{const t=state.tasks.find(t=>t.id===id);t.done=true;D.audit(state,user,'Reengajamento concluído',t.contactId,t.text);save();render();tasks();break}case'export-contacts':exportContacts();break;case'export-finance':exportFinance();break;case'export-report':exportFinance(true);break;case'delete-contact':{admin();const c=state.contacts.find(c=>c.id===id);if(state.payments.some(p=>p.contactId===id)){modal('Uma história que precisa ser preservada','<p>Este doador possui histórico financeiro e seu cadastro não pode ser excluído. Para encerrar a recorrência, altere o status para Cancelado.</p>',button('Voltar à ficha','profile',id));break}modal('Excluir este relacionamento?',`<p>O cadastro de <b>${esc(c.name)}</b> será removido. Esta ação requer confirmação.</p>`,button('Manter cadastro','profile',id)+button('Confirmar exclusão','confirm-delete',id,'danger'));break}case'confirm-delete':{admin();if(state.payments.some(p=>p.contactId===id))throw Error('Este contato possui histórico financeiro.');const c=state.contacts.find(c=>c.id===id);D.audit(state,user,'Contato excluído',null,c.name);state.contacts=state.contacts.filter(c=>c.id!==id);state.lists.forEach(l=>l.contacts=l.contacts.filter(x=>x!==id));state.tasks=state.tasks.filter(t=>t.contactId!==id);save();closeModal();render();toast('Cadastro excluído.');break}}}catch(err){toast(err.message,'error')}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});
['pointerdown','keydown'].forEach(event=>document.addEventListener(event,()=>{if(user&&Date.now()-lastActivity<=30*60*1000){lastActivity=Date.now();sessionStorage.setItem(SESSION,JSON.stringify({id:user.id,last:lastActivity}))}}));
setInterval(()=>{if(user){if(Date.now()-lastActivity>30*60*1000)logout('Sua sessão foi encerrada por inatividade.');else if(!state.users.find(u=>u.id===user.id)?.active)logout('Seu acesso foi inativado.')}},15000);
window.addEventListener('hashchange',()=>{if(!user){closeModal();render()}});
window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){try{state=JSON.parse(e.newValue);if(user){const u=state.users.find(u=>u.id===user.id);if(!u?.active){logout('Seu acesso foi inativado.');return}user=u;closeModal();render()}}catch{toast('Não foi possível sincronizar os dados deste navegador.','error')}}});
async function init(){try{const raw=localStorage.getItem(KEY);state=raw?JSON.parse(raw):D.seed();if(state.version!==1||!Array.isArray(state.contacts))throw Error('Dados locais incompatíveis.');if(!state.users.length){state.users=[{id:'admin',name:'Marina Costa',email:'admin@luz.exemplo',role:'Administrador',active:true,...await credentials('Esperanca@2026')},{id:'operator',name:'João Oliveira',email:'operador@luz.exemplo',role:'Operador de Captação',active:true,...await credentials('Esperanca@2026')}];save()}const rawSession=sessionStorage.getItem(SESSION),session=rawSession?JSON.parse(rawSession):null;if(session&&Date.now()-session.last<30*60*1000&&!location.hash.includes('redefinir=')){user=state.users.find(u=>u.id===session.id&&u.active);lastActivity=session.last}D.reconcile(state,{id:'system',name:'Sistema'});save();render()}catch(err){$('#app').innerHTML=`<div class="login-content" style="min-height:100vh"><div class="login-form">${brand()}<h2 style="margin-top:35px">Vamos preparar nosso espaço.</h2><p>${esc(err.message)}</p><p>Execute <b>node server.js</b> e abra <b>http://localhost:3000</b>.</p><small>Para remover dados locais incompatíveis, limpe o armazenamento deste site no navegador.</small></div></div>`}}
init();
function recipientMatches(){
  const query=($f('#email-recipient-search')?.value||'').trim().toLocaleLowerCase('pt-BR');
  return state.contacts.filter(c=>!query||[c.name,c.email].some(x=>x.toLocaleLowerCase('pt-BR').includes(query)));
}
function updateEmailRecipients(){
  const focusedId=document.activeElement?.dataset.action==='email-pick'?document.activeElement.dataset.id:null;
  cleanContactSelection();
  const matches=recipientMatches(),eligible=matches.filter(emailEligible),allSelected=eligible.length>0&&eligible.every(c=>selectedContacts.has(c.id));
  $f('#email-recipient-list').innerHTML=matches.map(c=>`<label class="recipient-option ${selectedContacts.has(c.id)?'is-picked':''} ${emailEligible(c)?'':'is-unavailable'}"><input type="checkbox" data-action="email-pick" data-id="${c.id}" ${selectedContacts.has(c.id)?'checked':''} ${emailEligible(c)?'':'disabled'} aria-label="Enviar e-mail para ${esc(c.name)}"><span class="recipient-text"><b>${esc(c.name)}</b><small>${esc(c.email||'Sem e-mail cadastrado')}</small>${!emailEligible(c)?`<span class="recipient-reason">${c.optOut?'Descadastrado de e-mails':'Sem e-mail válido'}</span>`:''}</span></label>`).join('')||empty('Nenhum contato encontrado.');
  $f('#email-selected-count').textContent=selectedContacts.size+' '+(selectedContacts.size===1?'destinatário selecionado':'destinatários selecionados');
  const all=$f('#email-select-all');all.checked=allSelected;all.indeterminate=!allSelected&&eligible.some(c=>selectedContacts.has(c.id));all.disabled=!eligible.length;
  $f('#email-filter-count').textContent=eligible.length+' disponíveis';
  $f('[type=submit]').disabled=selectedContacts.size===0;
  if(focusedId)$f('[data-action=email-pick][data-id="'+focusedId+'"]')?.focus({preventScroll:true});
}
function bulkEmailForm(draft={subject:'',body:''}){
  cleanContactSelection();
  formModal('Um e-mail para a nossa rede',`<div class="email-compose-grid"><div class="email-message"><div class="step-label">Sua mensagem</div>${field('Assunto *','subject',draft.subject,'text','required maxlength="180" placeholder="O que queremos compartilhar?"')}<div class="field"><label for="f-body">Mensagem *</label><textarea id="f-body" name="body" required maxlength="10000" rows="9" placeholder="Olá! Queremos compartilhar um pouco do que estamos construindo juntos…">${esc(draft.body)}</textarea></div><small>Revise a mensagem e os destinatários antes de confirmar.</small></div><section class="email-recipients" aria-label="Selecionar destinatários"><div class="step-label">Quem vai receber?</div><div class="search recipient-search">${icon('search')}<input id="email-recipient-search" type="search" placeholder="Buscar nome ou e-mail…" aria-label="Buscar destinatários"></div><div class="recipient-select-all"><label><input id="email-select-all" type="checkbox" data-action="email-select-all"> Selecionar todos da busca</label><small id="email-filter-count"></small></div><div id="email-recipient-list" class="check-list recipient-list"></div><div class="recipient-summary"><span id="email-selected-count" aria-live="polite"></span>${button('Limpar','email-clear','','quiet small')}</div><p class="recipient-help">Contatos descadastrados ou sem e-mail válido não podem ser selecionados.</p></section></div>`,d=>{
    cleanContactSelection();
    if(!selectedContacts.size)throw Error('Selecione pelo menos um destinatário.');
    if(!d.subject.trim()||!d.body.trim())throw Error('Informe o assunto e a mensagem.');
    reviewBulkEmail({subject:d.subject.trim(),body:d.body.trim()},[...selectedContacts]);
  },'Revisar envio',true);
  $f('#email-recipient-search').addEventListener('input',updateEmailRecipients);
  updateEmailRecipients();
}
function reviewBulkEmail(draft,ids){
  const recipients=ids.map(id=>state.contacts.find(c=>c.id===id)).filter(emailEligible);
  modal('Confira antes de enviar',`<div class="notice green"><b>${recipients.length} ${recipients.length===1?'destinatário':'destinatários'}</b> · ${esc(draft.subject)}</div><div class="email-review-grid"><section><h3 style="margin-bottom:12px">Sua mensagem</h3><div class="campaign-preview">${esc(draft.body)}</div></section><section><h3 style="margin-bottom:12px">Destinatários</h3><div class="review-recipient-list">${recipients.map(c=>`<div class="review-recipient"><b>${esc(c.name)}</b><small>${esc(c.email)}</small></div>`).join('')}</div></section></div>`,button('Voltar e editar','bulk-email-back')+button('Confirmar envio','bulk-email-send','','','mail'),true);
  $f('[data-action=bulk-email-back]').onclick=e=>{e.stopPropagation();bulkEmailForm(draft)};
  $f('[data-action=bulk-email-send]').onclick=e=>{
    e.stopPropagation();const btn=e.currentTarget;btn.disabled=true;
    try{activeUser();const count=D.send(state,user,ids,draft.subject,draft.body);save();selectedContacts.clear();closeModal();render();toast(count+' '+(count===1?'e-mail registrado':'e-mails registrados')+' no histórico de relacionamento.')}
    catch(err){btn.disabled=false;toast(err.message,'error')}
  };
}

$('#modal').addEventListener('close',()=>{if(!$('#modal').open&&user&&['contacts','donors'].includes(page))render()});
